spring-content-negotiation.solution:
def negotiate(accept, produces):
    entries = []
    for index, raw in enumerate((accept or "*/*").split(",")):
        parts = [p.strip().lower() for p in raw.split(";")]
        media = parts[0]
        if not media:
            continue
        q = 1.0
        for param in parts[1:]:
            if param.startswith("q="):
                q = float(param[2:])
        if q <= 0:
            continue
        specificity = 2 if media == "*/*" else 1 if media.endswith("/*") else 0
        entries.append((-q, specificity, index, media))
    if not entries and not (accept or "").strip():
        entries = [(-1.0, 2, 0, "*/*")]
    for _, _, _, media in sorted(entries):
        for candidate in produces:
            low = candidate.lower()
            if media == "*/*" or media == low or (media.endswith("/*") and low.split("/")[0] == media[:-2]):
                return candidate
    return "406 Not Acceptable"

spring-tx-propagation.solution:
class _Failure(Exception):
    pass


class _Tx:
    def __init__(self):
        self.rows = []
        self.rollback_only = False


def run(root):
    permanent = []
    clock = [0]

    def write(name, tx):
        clock[0] += 1
        (tx.rows if tx else permanent).append((clock[0], name))

    def body(node, tx):
        write(node["name"], tx)
        for child in node["calls"]:
            try:
                call(child, tx)
            except _Failure:
                if not child["caught"]:
                    raise
        if node["fails"]:
            raise _Failure("RuntimeException")

    def in_new_tx(node):
        tx = _Tx()
        body(node, tx)                      # an exception here discards tx.rows
        if tx.rollback_only:
            raise _Failure("UnexpectedRollbackException")
        permanent.extend(tx.rows)

    def joined(node, tx):
        try:
            body(node, tx)
        except _Failure:
            tx.rollback_only = True
            raise

    def call(node, tx):
        mode = node["propagation"]
        if mode == "REQUIRES_NEW" or (tx is None and mode in ("REQUIRED", "NESTED")):
            in_new_tx(node)
        elif mode == "MANDATORY" and tx is None:
            raise _Failure("IllegalTransactionStateException")
        elif mode == "NEVER" and tx is not None:
            raise _Failure("IllegalTransactionStateException")
        elif mode == "NOT_SUPPORTED" or mode == "NEVER" or (mode == "SUPPORTS" and tx is None):
            body(node, None)
        elif mode == "NESTED":
            mark, flag = len(tx.rows), tx.rollback_only
            try:
                body(node, tx)
            except _Failure:
                del tx.rows[mark:]
                tx.rollback_only = flag
                raise
        else:
            joined(node, tx)

    error = None
    try:
        call(root, None)
    except _Failure as failure:
        error = str(failure)
    return {"rows": [name for _, name in sorted(permanent)], "error": error}

