spring-n-plus-one.solution:
def count_queries(n, strategy, accesses, batch_size):
    queries = 1
    if strategy == "join-fetch":
        return queries
    if strategy == "eager-select":
        return queries + n
    if strategy == "subselect":
        return queries + (1 if accesses else 0)
    loaded = [False] * n
    for index in accesses:
        if loaded[index]:
            continue
        queries += 1
        loaded[index] = True
        if strategy == "batch":
            room = batch_size - 1
            for other in range(n):
                if room <= 0:
                    break
                if not loaded[other]:
                    loaded[other] = True
                    room -= 1
    return queries

